namespace fs=std::filesystem;
static std::string Hex(const std::vector<unsigned char>&v){std::ostringstream o;for(auto b:v)o<<std::hex<<std::setw(2)<<std::setfill('0')<<(int)b;return o.str();}
static std::wstring Msg(DWORD e){wchar_t*p=nullptr;DWORD n=FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER|FORMAT_MESSAGE_FROM_SYSTEM|FORMAT_MESSAGE_IGNORE_INSERTS,nullptr,e,0,(LPWSTR)&p,0,nullptr);std::wstring s=p&&n?p:L"unknown";if(p)LocalFree(p);return s;}
static bool Hash(const fs::path&p,std::string&o){BCRYPT_ALG_HANDLE a=nullptr;BCRYPT_HASH_HANDLE h=nullptr;DWORD n=0,z=0;if(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,nullptr,0)!=0||BCryptGetProperty(a,BCRYPT_OBJECT_LENGTH,(PUCHAR)&z,4,&n,0)!=0)return false;std::vector<unsigned char>x(z),d(32);if(BCryptCreateHash(a,&h,x.data(),z,nullptr,0,0)!=0)return false;std::ifstream f(p,std::ios::binary);std::vector<char>b(1<<20);while(f){f.read(b.data(),b.size());auto k=f.gcount();if(k&&BCryptHashData(h,(PUCHAR)b.data(),(ULONG)k,0)!=0)return false;}bool ok=BCryptFinishHash(h,d.data(),32,0)==0;BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(a,0);if(ok)o=Hex(d);return ok;}
int main(int ac,char**av){if(ac!=5){std::cerr<<"usage: reap-zero-prune-verify source staging expected-sha receipt\n";return 2;}fs::path s=fs::absolute(av[1]),d=fs::absolute(av[2]),r=fs::absolute(av[4]);std::error_code e;if(!fs::is_regular_file(s,e)){std::cerr<<"ZP01_FAIL=SOURCE_NOT_FILE\n";return 3;}fs::create_directories(d,e);if(e){std::cerr<<"ZP01_FAIL=STAGING_CREATE\n";return 3;}std::string sh;if(!Hash(s,sh)){std::cerr<<"ZP01_FAIL=SOURCE_HASH\n";return 4;}std::string ex=av[3];for(char&c:ex)c=(char)tolower((unsigned char)c);if(sh!=ex){std::cerr<<"ZP01_FAIL=SOURCE_HASH_MISMATCH\n";return 4;}char m[4];unsigned v=0,t=0,meta=0;std::ifstream f(s,std::ios::binary);f.read(m,4);f.read((char*)&v,4);f.read((char*)&t,4);f.read((char*)&meta,4);if(!f||std::string(m,4)!="GGUF"||(v!=2&&v!=3)){std::cerr<<"ZP01_FAIL=GGUF_HEADER\n";return 5;}ULARGE_INTEGER freeBytes{},total{},totalFree{};if(!GetDiskFreeSpaceExW(d.root_path().c_str(),&freeBytes,&total,&totalFree)){DWORD x=GetLastError();std::wcerr<<L"ZP01_FAIL=DISK_QUERY error="<<x<<L" message="<<Msg(x)<<L"\n";return 6;}auto sz=fs::file_size(s,e);if(e||freeBytes.QuadPart<sz+64ull*1024ull*1024ull){std::cerr<<"ZP01_FAIL=INSUFFICIENT_STAGING_SPACE\n";return 6;}fs::path tmp=d/(s.filename().wstring()+L".zp01.tmp"),c=d/s.filename();if(!CopyFileW(s.c_str(),tmp.c_str(),TRUE)){DWORD x=GetLastError();std::wcerr<<L"ZP01_FAIL=COPY error="<<x<<L" message="<<Msg(x)<<L" source="<<s.c_str()<<L" destination="<<tmp.c_str()<<L"\n";return 7;}std::string ch;if(fs::file_size(tmp,e)!=sz||!Hash(tmp,ch)||ch!=sh){DeleteFileW(tmp.c_str());std::cerr<<"ZP01_FAIL=CANDIDATE_VERIFY\n";return 8;}if(!MoveFileExW(tmp.c_str(),c.c_str(),MOVEFILE_WRITE_THROUGH)){DWORD x=GetLastError();DeleteFileW(tmp.c_str());std::wcerr<<L"ZP01_FAIL=PRIVATE_RENAME error="<<x<<L" message="<<Msg(x)<<L"\n";return 9;}std::ofstream q(r);q<<"{\"schema\":\"rawrxd.reap.zero_prune_private.001\",\"source_sha256\":\""<<sh<<"\",\"candidate_sha256\":\""<<ch<<"\",\"source_bytes\":"<<sz<<",\"candidate_bytes\":"<<sz<<",\"gguf_version\":"<<v<<",\"tensor_count_header\":"<<t<<",\"metadata_count_header\":"<<meta<<",\"candidate_private\":true,\"byte_identical\":true,\"source_unchanged\":true,\"tensor_inventory_verified\":false,\"reference_logit_parity\":false,\"publication\":false,\"rewrite_authorization\":false}\n";std::cout<<"ZP01_A_PASS receipt="<<r.string()<<"\n";return 0;}
